<template><div class="page"><div class="section-title"><div><div class="eyebrow">INCIDENT INVESTIGATION</div><h2>故障排查</h2><span class="muted">严重或不确定故障由 Background Remediation Agent 自动移交至此</span></div><n-button @click="load">刷新报告</n-button></div><div class="panel"><n-empty v-if="!items.length" description="暂无待人工介入的故障报告"/><n-list v-else hoverable><n-list-item v-for="i in items" :key="i.id" @click="router.push(`/app/incidents/${i.id}`)"><div class="incident-row"><div class="incident-badge">!</div><div><strong>{{i.alert_name}}</strong><div class="muted">{{contextSummary(i.context)}} · {{new Date(i.created_at).toLocaleString()}}</div></div></div><n-tag :type="i.status==='resolved'?'success':'warning'">{{i.status==='resolved'?'已解决':'待排查'}}</n-tag></n-list-item></n-list></div></div></template>
<script setup>import{ref,onMounted}from'vue';import{useRouter}from'vue-router';import{incidentApi}from'@/api';const router=useRouter(),items=ref([]);async function load(){items.value=(await incidentApi.list()).incidents||[]}function contextSummary(c){try{const v=typeof c==='string'?JSON.parse(c):c;return v?.repair_result||v?.reason||'等待 Agent 与人工联合排查'}catch{return'等待 Agent 与人工联合排查'}}onMounted(load)</script>
